<?php
/** Pause contract on guarded disposable WordPress/MariaDB. */
define('DOING_CRON',true);
define('EIPSI_STUDY_ENGINE_KEYRING',array('current'=>'HTTP_TEST','keys'=>array('HTTP_TEST'=>str_repeat('6b',32))));
define('EIPSI_STUDY_ENGINE_ACCESS_KEYRING',array('current'=>'ACCESS_TEST','keys'=>array('ACCESS_TEST'=>str_repeat('61',32))));
require __DIR__.'/m0/bootstrap.php';require_once EIPSI_FORMS_PLUGIN_DIR.'includes/study-engine/builder.php';
require __DIR__.'/study-engine/cross-sectional/support.php';require __DIR__.'/study-engine/persistence/support.php';require __DIR__.'/study-engine/longitudinal/support.php';
require_once EIPSI_FORMS_PLUGIN_DIR.'includes/study-engine/runtime/NativeBridge.php';
use EIPSI\StudyEngine\Runtime as R;use EIPSI\StudyEngine\Longitudinal as L;use EIPSI\StudyEngine\Persistence as P;use EIPSI\AssessmentEditor\Runtime as N;
$GLOBALS['pf_now']=gmdate('Y-m-d\TH:i:s\Z');$cases=array();$owned=array();$failed=0;$svc=new EIPSI\StudyEngine\Builder\Service(pf_db());
$sec2Mu=ABSPATH.'wp-content/mu-plugins/eipsi-sec2-environment.php';pe_assert(!file_exists($sec2Mu),'Fixture collision');wp_mkdir_p(dirname($sec2Mu));copy(__DIR__.'/sec2/environment.php',$sec2Mu);file_put_contents(ABSPATH.'wp-content/sec2-clock',(string)strtotime($GLOBALS['pf_now']));require$sec2Mu;
function s2_publish($future=false,$window=null){global$owned;$d=L\Configuration::apply(pe_definition(),array('verification_policy'=>'ALLOW_UNVERIFIED'));if($future)foreach($d['nodes']as&$n)if($n['id']==='E_ASSESSMENT')$n['schedule']['temporal_rule']=array('kind'=>'OFFSET','duration'=>array('kind'=>'ELAPSED','seconds'=>7200));unset($n);if($window!==null)foreach($d['nodes']as&$node)if(($node['completion_boundary']??null)==='ASSESSMENT')$node['schedule']['window']=array('kind'=>'DURATION','duration'=>array('kind'=>'ELAPSED','seconds'=>$window));unset($node);$p=pe_publish('simple',false,pe_native_transport_fixture($d));$owned[]=$p['definition']['study']['logical_id'];return$p;}
function s2_state($p,$state,$request=null){global$svc;$f=$svc->load($p['version']);return$svc->changeStudyState($p['version'],$f['lifecycle']['revision'],$state,false,$request??'SEC2_'.bin2hex(random_bytes(8)));}
function s2_native($p,$f){$_COOKIE[L\Identity::cookieName($p['public'])]=$f['token'];return R\NativeBridge::offer($f);}
function s2_time($value){$GLOBALS['pf_now']=$value;file_put_contents(ABSPATH.'wp-content/sec2-clock',(string)strtotime($value));}
function s2_domain($f){$block=$f['view']['next_action']['payload']['assessment_execution_id'];$graph=(new P\StudyVersionRepository(pf_db()))->compiled((new P\StudyVersionRepository(pf_db()))->find($f['version_id']));$answers=(new EIPSI\StudyEngine\Content\ResponseAdapter())->decode($f['definition'],array('R_q1'=>'Respuesta de dominio'),$graph->descendants($f['view']['snapshot']['instances'][$block]['definition_id']));return pf_dispatch($f,'SAVE_PAGE',array('block_execution_id'=>$block,'responses'=>$answers));}
function s2_owner(){return new N\Owner(null,static fn()=>strtotime($GLOBALS['pf_now']));}
$cases['PAUSED rejects creation of a new Native attempt for an existing participant']=function(){$p=s2_publish();$f=pf_enroll($p);s2_state($p,'PAUSED');pe_reject(fn()=>s2_native($p,$f),'STUDY_PAUSED');};
$cases['PAUSED rejects direct owner creation before scientific materialization']=function(){$p=s2_publish();$f=pf_enroll($p);s2_state($p,'PAUSED');pe_reject(fn()=>pf_owner()->create($p['version'],array('kind'=>'PARTICIPANT','id'=>$f['access']['participant_id']),'SEC2_LATE_CREATION'),'STUDY_PAUSED');};
$cases['PAUSED scheduler does not activate a future opportunity']=function(){$old=$GLOBALS['pf_now'];try{$p=s2_publish(true);$f=pf_enroll($p);s2_state($p,'PAUSED');$before=pf_owner()->view($f['access']['execution_id']);$GLOBALS['pf_now']=gmdate('Y-m-d\TH:i:s\Z',strtotime($old)+10800);(new L\Worker(pf_db(),pe_vault(),pf_caps(),pf_clock()))->advanceBatch(100);$after=pf_owner()->view($f['access']['execution_id']);pe_equal($before['snapshot'],$after['snapshot'],'Paused scheduler changed state');}finally{$GLOBALS['pf_now']=$old;}};
$cases['PAUSED existing Native partial can recover and complete']=function(){$p=s2_publish();$f=pf_enroll($p);$a=s2_native($p,$f);$o=s2_owner();$open=pf_native_fixture_command($o,$a['execution_id'],'open');$partial=pf_native_fixture_command($o,$a['execution_id'],'partial',array($open['definition']['elements'][0]['response_key']=>'Respuesta conservada'));$block=$f['view']['next_action']['payload']['assessment_execution_id'];$graph=(new P\StudyVersionRepository(pf_db()))->compiled((new P\StudyVersionRepository(pf_db()))->find($p['version']));$answers=(new EIPSI\StudyEngine\Content\ResponseAdapter())->decode($f['definition'],array('R_q1'=>'Respuesta dominio'),$graph->descendants($f['view']['snapshot']['instances'][$block]['definition_id']));pf_dispatch($f,'SAVE_PAGE',array('block_execution_id'=>$block,'responses'=>$answers));s2_state($p,'PAUSED');$again=$o->view($a['execution_id']);pe_equal($partial['session'],$again['session'],'Recovery changed state');$done=pf_native_fixture_command($o,$a['execution_id'],'submit');pe_assert($done['state']==='COMPLETED','Paused completion rejected');};
$cases['PAUSED cannot enroll a new subject']=function(){$p=s2_publish();s2_state($p,'PAUSED');$f=pf_enroll($p);pe_assert(isset($f['entry']),'Created participation');};
$cases['Resume preserves existing seed and does not duplicate opportunities']=function(){$p=s2_publish();$f=pf_enroll($p);$before=pf_owner()->view($f['access']['execution_id']);s2_state($p,'PAUSED');s2_state($p,'ACTIVE');$after=pf_owner()->view($f['access']['execution_id']);pe_equal($before['snapshot'],$after['snapshot'],'State changed by lifecycle');};

$cases['Public portal resumes the same open attempt during PAUSED']=function(){$p=s2_publish();$f=pf_enroll($p);$a=s2_native($p,$f);s2_state($p,'PAUSED');$r=pf_http($p['public'],array(new WP_Http_Cookie(array('name'=>L\Identity::cookieName($p['public']),'value'=>$f['token']))));pe_assert($r['status']===200&&$r['data']['state']==='OPEN_ASSESSMENT','Portal did not continue: '.substr($r['body'],0,100));};
$cases['Public portal shows only paused message for a new visitor']=function(){$p=s2_publish();s2_state($p,'PAUSED');$r=pf_http($p['public']);pe_assert($r['status']===200&&$r['data']['state']==='PAUSED'&&strpos($r['data']['html'],'name="email"')===false,'New entry offered');};
$cases['Existing participant without an open attempt cannot access portal or direct admission']=function(){$p=s2_publish();$f=pf_enroll($p);s2_state($p,'PAUSED');pe_reject(fn()=>pf_runtime()->handle($p['public'],$f['token']),'STUDY_PAUSED');$r=pf_http($p['public'],array(new WP_Http_Cookie(array('name'=>L\Identity::cookieName($p['public']),'value'=>$f['token']))));pe_assert($r['data']['state']==='PAUSED','Portal created a new assessment');};
$cases['Changing browser ownership never grants another participant an existing attempt']=function(){$p=s2_publish();$a=pf_enroll($p);$id=s2_native($p,$a)['execution_id'];$b=pf_enroll($p);s2_state($p,'PAUSED');$_COOKIE[L\Identity::cookieName($p['public'])]=$b['token'];pe_reject(fn()=>s2_owner()->view($id),'Access required');};
$cases['A remembered URL or unlinked cookie cannot admit a paused anonymous study']=function(){$p=pe_publish();$GLOBALS['owned'][]=$p['definition']['study']['logical_id'];$f=pe_runtime()->handle($p['public']);s2_state($p,'PAUSED');pe_reject(fn()=>pe_runtime()->handle($p['public'],$f['token']),'STUDY_PAUSED');};
$cases['Admin assign cannot create a Study Native execution while paused']=function(){$p=s2_publish();$f=pf_enroll($p);$block=$f['view']['next_action']['payload']['assessment_execution_id'];$v=null;foreach($p['definition']['nodes']as$n)if($n['id']===$f['view']['snapshot']['instances'][$block]['definition_id'])$v=$n['metadata']['native_version_id'];s2_state($p,'PAUSED');pe_reject(fn()=>s2_owner()->assign($v,array('kind'=>'STUDY_SESSION','public_id'=>$p['public'],'execution_id'=>$f['access']['execution_id'],'study_version_id'=>$p['version'],'participant_id'=>$f['access']['participant_id'])),'STUDY_PAUSED');};
$cases['Expired scientific window remains closed during PAUSED']=function(){$saved=$GLOBALS['pf_now'];try{$p=s2_publish(false,120);$f=pf_enroll($p);$id=s2_native($p,$f)['execution_id'];s2_state($p,'PAUSED');$before=(new N\Store())->find('executions',$id);s2_time(gmdate('Y-m-d\TH:i:s\Z',strtotime($saved)+121));pe_reject(fn()=>s2_owner()->view($id),'Assessment unavailable');pe_equal($before,(new N\Store())->find('executions',$id),'Expiry created or changed an attempt');}finally{s2_time($saved);}};
$cases['PAUSED defers new availability even for an already assigned attempt']=function(){$p=s2_publish();$f=pf_enroll($p);s2_native($p,$f);s2_state($p,'PAUSED');$i=pf_intents($f['access']['execution_id'],'ASSESSMENT_AVAILABLE')[0];$before=count($GLOBALS['m0_mail']??array());$r=pf_delivery($i);pe_assert(!$r['success']&&isset($r['defer_until'])&&count($GLOBALS['m0_mail']??array())===$before,'New availability delivered');};
$cases['Pause and Resume lifecycle retries are idempotent and auditable']=function(){global$svc;$p=s2_publish();$one=s2_state($p,'PAUSED','SEC2_PAUSE_REPLAY');$two=$svc->changeStudyState($p['version'],$one['lifecycle']['revision']-1,'PAUSED',false,'SEC2_PAUSE_REPLAY');pe_assert($one['lifecycle']===$two['lifecycle'],'Pause replay changed state');$same=s2_state($p,'PAUSED');pe_assert($same['lifecycle']===$one['lifecycle'],'Repeated pause changed revision');$a=s2_state($p,'ACTIVE','SEC2_RESUME_REPLAY');$b=$svc->changeStudyState($p['version'],$a['lifecycle']['revision']-1,'ACTIVE',false,'SEC2_RESUME_REPLAY');pe_assert($a['lifecycle']===$b['lifecycle'],'Resume replay changed state');$rows=pf_db()->rows(pf_db()->prepare('SELECT details_json FROM '.pf_db()->table('management_events')." WHERE study_id=%s AND action='STUDY_STATE_CHANGED'",$p['definition']['study']['logical_id']));pe_assert(count($rows)===2,'Missing or duplicate lifecycle audit');};

$cases['Reminder of a valid in-progress attempt still sends during PAUSED']=function(){$saved=$GLOBALS['pf_now'];try{$p=s2_publish();$f=pf_enroll($p);$a=s2_native($p,$f);pf_native_fixture_command(s2_owner(),$a['execution_id'],'open');s2_state($p,'PAUSED');$reminder=pf_intents($f['access']['execution_id'],'ASSESSMENT_REMINDER')[0];s2_time(gmdate('Y-m-d\TH:i:s\Z',strtotime($reminder['trigger_at'].' UTC')));$before=count($GLOBALS['m0_mail']??array());pe_assert(pf_delivery($reminder)['success'],'Reminder stopped by pause');pe_assert(count($GLOBALS['m0_mail']??array())===$before+1,'No reminder delivered');}finally{s2_time($saved);}};
$cases['Completion during PAUSED stops later reminders']=function(){$saved=$GLOBALS['pf_now'];try{$p=s2_publish();$f=pf_enroll($p);$id=s2_native($p,$f)['execution_id'];pf_native_fixture_command(s2_owner(),$id,'open');s2_domain($f);$reminder=pf_intents($f['access']['execution_id'],'ASSESSMENT_REMINDER')[0];s2_state($p,'PAUSED');pf_native_fixture_command(s2_owner(),$id,'submit');s2_time(gmdate('Y-m-d\TH:i:s\Z',strtotime($reminder['trigger_at'].' UTC')));$before=count($GLOBALS['m0_mail']??array());pe_assert(pf_delivery($reminder)['success'],'Cancelled reminder not resolved');pe_assert(count($GLOBALS['m0_mail']??array())===$before,'Completed attempt reminded');}finally{s2_time($saved);}};
$cases['Due date elapsing during PAUSED stops reminders without extension']=function(){$saved=$GLOBALS['pf_now'];try{$p=s2_publish(false,3600);$f=pf_enroll($p);$id=s2_native($p,$f)['execution_id'];pf_native_fixture_command(s2_owner(),$id,'open');$b=$f['view']['next_action']['payload']['assessment_execution_id'];$due=$f['view']['snapshot']['instances'][$b]['due_at'];$r=pf_intents($f['access']['execution_id'],'ASSESSMENT_REMINDER')[0];s2_state($p,'PAUSED');s2_time(gmdate('Y-m-d\TH:i:s\Z',strtotime($due)+1));$before=count($GLOBALS['m0_mail']??array());pe_assert(pf_delivery($r)['success'],'Expired intent not resolved');pe_assert(count($GLOBALS['m0_mail']??array())===$before,'Expired attempt reminded');$row=pf_db()->row(pf_db()->prepare('SELECT state,due_at FROM '.pf_db()->table('block_executions').' WHERE id=%s',$b));pe_assert($row['state']==='EXPIRED'&&$row['due_at']===P\Database::date($due),'Window extended');}finally{s2_time($saved);}};
$cases['Memory session expiry reuses the same eligible attempt during PAUSED']=function(){$saved=$GLOBALS['pf_now'];try{$p=s2_publish();$f=pf_enroll($p);$id=s2_native($p,$f)['execution_id'];$open=pf_native_fixture_command(s2_owner(),$id,'open');s2_state($p,'PAUSED');s2_time(gmdate('Y-m-d\TH:i:s\Z',$open['expires_at']+1));$r=s2_owner()->view($id);pe_assert($r['execution_id']===$id&&$r['session_reset']&&$r['session']===null,'Recovery replaced attempt');pe_assert(s2_native($p,$f)['execution_id']===$id,'Reassignment duplicated attempt');}finally{s2_time($saved);}};
$cases['Resume catches up at the exact clock already persisted during Pause']=function(){$saved=$GLOBALS['pf_now'];try{$p=s2_publish(true);$f=pf_enroll($p);s2_state($p,'PAUSED');s2_time(gmdate('Y-m-d\TH:i:s\Z',strtotime($saved)+10800));$v=pf_owner()->view($f['access']['execution_id']);pf_owner()->dispatch($f['access']['execution_id'],array('id'=>'SEC2_PAUSED_CLOCK','kind'=>'ADVANCE_TIME','expected_revision'=>$v['revision'],'data'=>array('at'=>$GLOBALS['pf_now'])));s2_state($p,'ACTIVE');$w=new L\Worker(pf_db(),pe_vault(),pf_caps(),pf_clock());$w->advanceBatch(100);$one=pf_owner()->view($f['access']['execution_id']);pe_assert($one['next_action']['kind']==='OPEN_ASSESSMENT','Same-clock resume left future opportunity scheduled');$w->advanceBatch(100);pe_equal($one['snapshot'],pf_owner()->view($f['access']['execution_id'])['snapshot'],'Same-clock replay changed state');}finally{s2_time($saved);}};
$cases['Delivery after Resume catches up the same persisted clock before eligibility']=function(){$saved=$GLOBALS['pf_now'];try{$p=s2_publish(true);$f=pf_enroll($p);$intent=pf_intents($f['access']['execution_id'],'ASSESSMENT_AVAILABLE')[0];s2_state($p,'PAUSED');s2_time(gmdate('Y-m-d\TH:i:s\Z',strtotime($saved)+10800));$v=pf_owner()->view($f['access']['execution_id']);pf_owner()->dispatch($f['access']['execution_id'],array('id'=>'SEC2_PAUSED_DELIVERY_CLOCK','kind'=>'ADVANCE_TIME','expected_revision'=>$v['revision'],'data'=>array('at'=>$GLOBALS['pf_now'])));s2_state($p,'ACTIVE');$result=pf_delivery($intent);$row=pf_db()->row(pf_db()->prepare('SELECT state,cancel_reason FROM '.pf_db()->table('notification_intents').' WHERE id=%s',$intent['id']));pe_assert($row['state']==='SENT','Same-clock delivery lost availability: '.json_encode(array($row,$result)));}finally{s2_time($saved);}};
$cases['Resume catches up an elapsed future availability once']=function(){$saved=$GLOBALS['pf_now'];try{$p=s2_publish(true);$f=pf_enroll($p);s2_state($p,'PAUSED');s2_time(gmdate('Y-m-d\TH:i:s\Z',strtotime($saved)+10800));$w=new L\Worker(pf_db(),pe_vault(),pf_caps(),pf_clock());$w->advanceBatch(100);s2_state($p,'ACTIVE');$w->advanceBatch(100);$one=pf_owner()->view($f['access']['execution_id']);$w->advanceBatch(100);pe_equal($one['snapshot'],pf_owner()->view($f['access']['execution_id'])['snapshot'],'Duplicate catchup');pe_assert($one['next_action']['kind']==='OPEN_ASSESSMENT','No catchup');}finally{s2_time($saved);}};
$cases['Future randomization remains unresolved until Resume']=function(){$saved=$GLOBALS['pf_now'];try{$p=pf_publish('06',array('verification_policy'=>'ALLOW_UNVERIFIED'));$GLOBALS['owned'][]=$p['definition']['study']['logical_id'];$f=pf_enroll($p);$id=$f['view']['next_action']['payload']['assessment_execution_id'];pf_dispatch($f,'OPEN_ASSESSMENT',array('block_execution_id'=>$id));s2_state($p,'PAUSED');$f=pf_runtime()->handle($p['public'],$f['token']);try{$done=pf_runtime()->handle($p['public'],$f['token'],pe_request($f,'submit',array('RESPONSE_Q_ELIGIBLE'=>'true')));}catch(Throwable$e){$probe=pf_owner()->view($f['access']['execution_id']);throw new RuntimeException($e->getMessage().' / '.json_encode($probe['next_action']??null),0,$e);}pe_assert(!$done['view']['snapshot']['random_decisions'],'Future draw resolved during pause');s2_state($p,'ACTIVE');s2_time(gmdate('Y-m-d\TH:i:s\Z',strtotime($saved)+1));$w=new L\Worker(pf_db(),pe_vault(),pf_caps(),pf_clock());$w->advanceBatch(100);$after=pf_owner()->view($f['access']['execution_id']);pe_assert(count($after['snapshot']['random_decisions'])===1,'Draw did not resolve once');$w->advanceBatch(100);pe_equal($after['snapshot']['random_decisions'],pf_owner()->view($f['access']['execution_id'])['snapshot']['random_decisions'],'Rerandomized');}finally{s2_time($saved);}};
require __DIR__.'/sec2/races.php';require __DIR__.'/sec2/logical.php';
try{foreach($cases as$name=>$fn){try{$fn();echo 'PASS '.$name."\n";}catch(Throwable$e){$failed++;echo 'FAIL '.$name.': '.$e->getMessage()."\n";}}}finally{unlink($sec2Mu);unlink(ABSPATH.'wp-content/sec2-clock');wp_set_current_user(1);foreach($owned as$study){try{$svc->deleteStudy($study,'ELIMINAR '.$study);}catch(Throwable$e){$failed++;echo 'FAIL cleanup: '.$e->getMessage()."\n";}}}
echo count($cases).' tests, '.$failed." failures\n";ob_end_flush();exit($failed?1:0);
